java.io.File destDir = outputPath.toFile();
destDir.mkdirs();

java.util.List<java.io.File> inputFiles = java.util.Arrays.asList(
    new java.io.File(grid_png), 
    new java.io.File(grid_jpeg)
);

java.util.List<java.io.File> resultFiles;
try {
    resultFiles = net.coobird.thumbnailator.Thumbnails.fromFiles(inputFiles)
        .size(200, 200)
        .asFiles(destDir, net.coobird.thumbnailator.name.Rename.PREFIX_HYPHEN_THUMBNAIL);
} catch (java.io.IOException e) {
    throw new RuntimeException("Failed to process and save thumbnails", e);
}

assert resultFiles != null && resultFiles.size() == 2 : "Expected exactly 2 files to be created";

java.io.File firstFile = resultFiles.get(0);
assert firstFile.exists() : "Output file should exist on disk";
assert firstFile.getParentFile().getAbsoluteFile().equals(destDir.getAbsoluteFile()) : "Output file should be located in the destination directory";
assert firstFile.getName().startsWith("thumbnail-") : "Output file should have the correct rename prefix";

java.awt.image.BufferedImage resized;
try {
    resized = javax.imageio.ImageIO.read(firstFile);
} catch (java.io.IOException e) {
    throw new RuntimeException("Failed to read the generated thumbnail", e);
}

assert resized != null : "Generated thumbnail could not be decoded";
assert resized.getWidth() <= 200 && resized.getHeight() <= 200 : "Image should be resized to fit within 200x200 bounding box";

System.out.println("__CHECK__ asFiles " + resultFiles.size() + " files, first: " + firstFile.getName());

